WITH with_windows AS (SELECT *, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel), 4) AS discount_pct_share, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY starts_on, id) AS event_seq_2 FROM promotions) SELECT CASE WHEN event_seq >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS event_seq_tier, APPROX_PERCENTILE(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, PERCENTILE_APPROX(event_seq_2, 0.9) AS event_seq_2_p90, ROUND(AVG(discount_pct_share), 2) AS avg_discount_pct_share, COUNT(*) FILTER (WHERE channel = 'web') AS web_rows, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows FROM with_windows GROUP BY event_seq_tier ORDER BY avg_discount_pct_share DESC
